import{_ as e,o as t,c as a,Q as s}from"./chunks/framework.b67c47e6.js";const m=JSON.parse('{"title":"Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1792317257000}'),n={name:"guide/index.md"},o=s('<h1 id="guide" tabindex="-1">Guide <a class="header-anchor" href="#guide" aria-label="Permalink to &quot;Guide&quot;">​</a></h1><p>The Guide explains the interface and functionality across the produuz.it platform. Use these pages as a reference for each feature area.</p><h2 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to &quot;Sections&quot;">​</a></h2><ul><li><strong><a href="/guide/viewer/">Viewer</a></strong> — The 3D production viewer: visualize designs, track checklists, and manage station workflows.</li><li><strong><a href="/guide/properties/">Properties in Texts</a></strong> — The <code>{property}</code> names you can use in the viewer header, the list hint and the machine file fields.</li><li><strong><a href="/guide/panel_coordinates/">Panel Sides and Coordinates</a></strong> — Front and back, inside and outside, zones, axes and origin of a panel, and which side each screen and machine file looks from.</li><li><strong><a href="/guide/management/">Management</a></strong> — Company settings, users, projects, production lines, IFC parsing setup, and machines.</li><li><strong><a href="/guide/management/dashboard/">Dashboard</a></strong> — Production indicators for managers.</li><li><strong><a href="/guide/reports/">Reports</a></strong> — Generate Bills of Materials, production spreadsheets, quality control reports, QR stickers, and more.</li><li><strong><a href="/guide/machine_files/">Machine Files</a></strong> — How machine files are made, and every file format and machine (MOB, BTL, BVX, XCS, DXF, etc.).</li><li><strong><a href="/guide/planning/">Production Planning</a></strong> — Schedule constructibles on a calendar with drag-and-drop and workload tracking.</li><li><strong><a href="/guide/quantities/">Quantities</a></strong> — Plan design quantities across project phases and batches.</li><li><strong><a href="/guide/issues/">Issues Management</a></strong> — Track production issues and quality control records.</li><li><strong><a href="/guide/logistics/">Logistics</a></strong> — Material tracking, part batches and kits.</li><li><strong><a href="/guide/logistics/delivery/">Delivery &amp; Racks</a></strong> — Rack setups, rack loads and the Delivery screen.</li><li><strong><a href="/guide/stock/">Sizes and Materials</a></strong> — Manage your material catalog: materials, sizes, and products.</li><li><strong><a href="/guide/integrations/">Integrations &amp; Webhooks</a></strong> — Receive notifications in external systems when events occur.</li><li><strong><a href="/guide/account/">Account Settings</a></strong> — Personal settings, 2FA, and notification preferences.</li><li><strong><a href="/guide/api/">API</a></strong> — REST API overview, authentication, and available endpoints.</li><li><strong><a href="/guide/mcp/">Claude connector (MCP)</a></strong> — Ask Claude about your production data.</li></ul><h2 id="row-buttons" tabindex="-1">Row buttons <a class="header-anchor" href="#row-buttons" aria-label="Permalink to &quot;Row buttons&quot;">​</a></h2><p>The last column of a list holds the buttons of each row. They are always shown, in the same place in every list:</p><ul><li><strong>One or two buttons</strong> for what you do most with that item, such as download, view, edit or solve. Hover one with the mouse to see its name.</li><li><strong>⋮ (More actions)</strong> opens the rest, each with its name. <strong>Delete</strong> is always the last item of that menu, in red, and asks for confirmation before anything is deleted.</li><li>An action that does not apply to the item right now stays in its place, greyed out, sometimes with the reason next to it (for example <em>Already final</em>).</li></ul><p>Lists where you can tick rows, such as <strong>Constructibles</strong> and <strong>Designs</strong>, show the buttons that act on the ticked rows above the table, next to the <strong>All / Modules / Assemblies</strong> selector. They are always there and stay greyed out until you tick a row. <strong>Refresh</strong>, at the top right, loads the list again.</p><p>On a tablet the buttons and the menu items are larger, to be easy to tap.</p><h2 id="lists-on-a-phone" tabindex="-1">Lists on a phone <a class="header-anchor" href="#lists-on-a-phone" aria-label="Permalink to &quot;Lists on a phone&quot;">​</a></h2><p>On a phone, the management lists (files, designs, constructibles, parts, issues, reports, part batches, multipanel groups, rack setups and the settings lists) show one short row per item: its name, two or three facts under it, and its status at the end.</p><ul><li><strong>Tap a row</strong> to open it. An item with a detail panel opens it. The others open a sheet from the bottom of the screen with all their fields and, under them, the same actions as on a computer, each with its name and in the same order, <strong>Delete</strong> last.</li><li><strong>To act on several items</strong>, tap <strong>Select</strong>, tick the items, then tap <strong>Actions</strong> in the bar at the bottom. Tap <strong>Done</strong> to leave.</li><li><strong>Filters</strong> fold into a <strong>Filters</strong> button, which shows how many filters are on. Tap it to change them, then <strong>Done</strong>.</li></ul><p>Tablets and computers show the full tables, as before.</p>',13),i=[o];function r(l,h,d,c,g,u){return t(),a("div",null,i)}const f=e(n,[["render",r]]);export{m as __pageData,f as default};
